import freemarker.template.TemplateExceptionHandler;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;

public class TemplateService {

    // Freemarker Configuration is thread-safe after initialization.
    // Initialized once statically for optimal performance.
    private static final Configuration FREEMARKER_CONFIG;

    static {
        FREEMARKER_CONFIG = new Configuration(Configuration.VERSION_2_3_31);
        FREEMARKER_CONFIG.setDefaultEncoding("UTF-8");
        FREEMARKER_CONFIG.setTemplateExceptionHandler(TemplateExceptionHandler.RETHROW_HANDLER);
        FREEMARKER_CONFIG.setLogTemplateExceptions(false);
        FREEMARKER_CONFIG.setWrapUncheckedExceptions(true);
    }

    /**
     * Renders a user profile page using the provided Freemarker template content.
     *
     * @param username       The username to inject into the template
     * @param templateContent The raw Freemarker template string provided by the user
     * @return The rendered HTML string
     */
    public String renderUserProfile(String username, String templateContent) {
        try {
            // Create template directly from string content
            Template template = new Template("userProfile", new StringReader(templateContent), FREEMARKER_CONFIG);

            // Prepare data model
            Map<String, Object> dataModel = new HashMap<>();
            dataModel.put("username", username);

            // Process template
            StringWriter writer = new StringWriter();
            template.process(dataModel, writer);
            return writer.toString();
        } catch (TemplateException | IOException e) {
            throw new RuntimeException("Failed to render user profile template", e);
        }
    }
}

